using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;

namespace Casino.EditorTools
{
    /// <summary>
    /// Import rules for the 3D staff (generated by Tools/make_staff.py) and the CC0 animation libraries:
    /// humanoid avatars so every animation retargets onto every character, light meshes and phone-sized textures.
    /// </summary>
    public sealed class StaffImporter : AssetPostprocessor
    {
        public const string StaffRoot = "Assets/Resources/Staff/";
        public const string AnimRoot = "Assets/Characters/Animations/";
        public const string ControllerPath = "Assets/Resources/Staff/StaffAnimator.controller";

        // Bump whenever these rules change, so Unity re-imports the staff with them (2: no mesh compression, sharper skin).
        public override uint GetVersion() => 2;

        void OnPreprocessModel()
        {
            var mi = (ModelImporter)assetImporter;
            if (assetPath.StartsWith(StaffRoot))
            {
                mi.animationType = ModelImporterAnimationType.Human;
                mi.avatarSetup = ModelImporterAvatarSetup.CreateFromThisModel;
                mi.importAnimation = false;
                mi.importBlendShapes = false;
                mi.importCameras = false;
                mi.importLights = false;
                mi.importVisibility = false;
                // No mesh compression: it quantises normals, which per-pixel lighting shows as blotches on the faces.
                // (It only shrinks the download; the mesh is uncompressed in memory either way.)
                mi.meshCompression = ModelImporterMeshCompression.Off;
                mi.importTangents = ModelImporterTangents.None;
                mi.materialImportMode = ModelImporterMaterialImportMode.ImportViaMaterialDescription;
                mi.optimizeGameObjects = false;
                mi.isReadable = false;
            }
            else if (assetPath.StartsWith(AnimRoot))
            {
                mi.animationType = ModelImporterAnimationType.Human;
                mi.avatarSetup = ModelImporterAvatarSetup.CreateFromThisModel;
                mi.importAnimation = true;
                mi.materialImportMode = ModelImporterMaterialImportMode.None;
                mi.meshCompression = ModelImporterMeshCompression.High;
                mi.animationCompression = ModelImporterAnimationCompression.Optimal;
            }
        }

        void OnPreprocessAnimation()
        {
            if (!assetPath.StartsWith(AnimRoot)) return;
            var mi = (ModelImporter)assetImporter;
            var clips = mi.defaultClipAnimations;
            foreach (var clip in clips)
            {
                clip.name = Clean(clip.name);
                clip.loopTime = clip.name.Contains("Loop");
                clip.lockRootRotation = clip.lockRootHeightY = clip.lockRootPositionXZ = true;
                clip.keepOriginalOrientation = clip.keepOriginalPositionY = clip.keepOriginalPositionXZ = true;
            }
            mi.clipAnimations = clips;
        }

        void OnPreprocessTexture()
        {
            if (!assetPath.StartsWith(StaffRoot)) return;
            var ti = (TextureImporter)assetImporter;
            string name = Path.GetFileNameWithoutExtension(assetPath).ToLowerInvariant();
            bool skin = name.Contains("skin") || name.Contains("female_diffuse") || name.Contains("male_diffuse") || name.Contains("young_");
            bool cutout = name.Contains("hair") || name.Contains("long") || name.Contains("bob") || name.Contains("ponytail") || name.Contains("short")
                          || name.Contains("braid") || name.Contains("eyebrow") || name.Contains("eyelash");
            ti.maxTextureSize = skin ? 2048 : 512;   // the face is a small part of the body's skin texture
            ti.mipmapEnabled = true;
            ti.alphaIsTransparency = cutout;
            ti.textureCompression = TextureImporterCompression.Compressed;
            var android = ti.GetPlatformTextureSettings("Android");
            android.overridden = true;
            android.maxTextureSize = ti.maxTextureSize;
            android.format = cutout || skin || name.Contains("eye") ? TextureImporterFormat.ASTC_6x6 : TextureImporterFormat.ASTC_8x8;
            ti.SetPlatformTextureSettings(android);
        }

        static string Clean(string clipName)
        {
            int bar = clipName.LastIndexOf('|');
            return bar >= 0 ? clipName.Substring(bar + 1) : clipName;
        }

        /// <summary>States the staff animator offers (state name = clip name in the CC0 libraries).</summary>
        public static readonly string[] States =
        {
            "Idle_Loop", "Idle_Talking_Loop", "Walk_Formal_Loop", "Walk_Loop", "PickUp_Table", "Interact", "Idle_Rail_Loop",
            "Idle_Rail_Call", "Yes", "Dance_Loop", "Idle_FoldArms_Loop", "Sitting_Idle_Loop", "Sitting_Talking_Loop", "Consume",
        };

        /// <summary>Builds (or rebuilds) the shared animator: one state per clip, IK enabled for eye contact and hand poses.</summary>
        [MenuItem("Casino/Staff/Rebuild Staff Animator")]
        public static void BuildController()
        {
            var clips = AssetDatabase.FindAssets("t:Model", new[] { AnimRoot.TrimEnd('/') })
                .Select(AssetDatabase.GUIDToAssetPath)
                .SelectMany(AssetDatabase.LoadAllAssetsAtPath)
                .OfType<AnimationClip>()
                .Where(c => !c.name.StartsWith("__preview__"))
                .GroupBy(c => c.name)
                .ToDictionary(g => g.Key, g => g.First());
            if (clips.Count == 0)
            {
                Debug.LogWarning("Casino: no staff animation clips found under " + AnimRoot);
                return;
            }
            Directory.CreateDirectory(Path.GetDirectoryName(ControllerPath));
            AssetDatabase.DeleteAsset(ControllerPath);
            var controller = AnimatorController.CreateAnimatorControllerAtPath(ControllerPath);
            var layers = controller.layers;
            layers[0].iKPass = true;
            controller.layers = layers;
            var machine = controller.layers[0].stateMachine;
            foreach (var state in States)
            {
                if (!clips.TryGetValue(state, out var clip))
                {
                    Debug.LogWarning("Casino: missing staff animation " + state);
                    continue;
                }
                var s = machine.AddState(state);
                s.motion = clip;
                s.iKOnFeet = true;
                if (state == "Idle_Loop") machine.defaultState = s;
            }
            AssetDatabase.SaveAssets();
            Debug.Log($"Casino: staff animator built with {machine.states.Length} states from {clips.Count} clips.");
        }

        /// <summary>Called before builds: make sure the animator exists.</summary>
        public static void EnsureController()
        {
            if (AssetDatabase.LoadAssetAtPath<AnimatorController>(ControllerPath) == null) BuildController();
        }
    }
}
